<?php $items=$vehicles??[];$properties=$propertyOptions??[];$people=$personOptions??[];$zkLevels=$zkAccessLevels??[];?>
<div class="d-flex flex-wrap justify-content-between gap-2 align-items-start mb-3"><div><h4 class="mb-1"><i class="bi bi-car-front-fill me-2"></i>Vehículos</h4><p class="text-body-secondary mb-0">Registro Property + credenciales. En Premier, el autenticador vehicular real es la etiqueta RFID del parabrisas (cardNo ZK); la placa se conserva como identidad/LPR posible.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#vehicleAdminModal"><i class="bi bi-plus-lg"></i> Nuevo vehículo</button></div>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Vehículo</th><th>Placa</th><th>RFID / tarjeta</th><th>Unidad</th><th>Persona</th><th>Datos</th><th>ZKBio</th><th></th></tr></thead><tbody><?php foreach($items as $v):$s=(string)($v['external_sync_status']??'not_requested');$vehicleLabel=trim((string)($v['display_name']??''))?:trim((string)($v['make']??'').' '.(string)($v['model']??''))?:((string)($v['plate']??'')?:('Vehículo #'.$v['id']));?><tr><td><strong><?=e($vehicleLabel)?></strong></td><td><?=!empty($v['plate'])?e($v['plate']):'<span class="text-body-secondary">Sin placa</span>'?></td><td><code><?=e($v['rfid_card_no']??'—')?></code></td><td><?=e($v['property_name'])?></td><td><?=e($v['person_name']??'—')?></td><td><?=e(trim((string)($v['make']??'').' '.(string)($v['model']??'')))?><?=!empty($v['color'])?' · '.e($v['color']):''?></td><td><span class="badge text-bg-<?=e(match($s){'synced'=>'success','pending'=>'warning','error'=>'danger','warning'=>'secondary',default=>'light'})?>"><?=e($s)?></span><?php if(!empty($v['external_error'])):?><small class="d-block text-danger"><?=e($v['external_error'])?></small><?php endif;?></td><td class="text-end text-nowrap"><button class="btn btn-sm btn-outline-secondary js-edit-vehicle" data-bs-toggle="modal" data-bs-target="#vehicleAdminModal" data-json='<?=e(json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-pencil"></i> Editar</button> <form method="post" action="<?=url('vehicle-zkbio-sync')?>" class="d-inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($v['id'])?>"><button class="btn btn-sm btn-outline-primary"><i class="bi bi-arrow-repeat"></i> ZKBio</button></form></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="8" class="text-center text-body-secondary py-4">No hay vehículos registrados.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal fade" id="vehicleAdminModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form class="modal-content" method="post" action="<?=url('vehicle-save')?>"><?=csrf_field()?><input type="hidden" name="id" id="vehicleId"><div class="modal-header"><h5 class="modal-title" id="vehicleModalTitle">Nuevo vehículo</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="form-label">Nombre / identificación visual</label><input class="form-control" name="display_name" id="vehicleDisplay" placeholder="Ej. Toyota 4Runner / Vehículo Sr. Pérez"></div><div class="col-md-6"><label class="form-label">Unidad</label><select class="form-select" name="property_id" id="vehicleProperty" required><option value="">Seleccione…</option><?php foreach($properties as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Persona</label><select class="form-select" name="person_id" id="vehiclePerson"><option value="">Sin persona</option><?php foreach($people as $p):?><option value="<?=e($p['id'])?>"><?=e($p['display_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Placa</label><input class="form-control" name="plate" id="vehiclePlate" style="text-transform:uppercase"></div><div class="col-md-6"><label class="form-label">Etiqueta RFID / cardNo ZK</label><input class="form-control" name="rfid_card_no" inputmode="numeric" id="vehicleRfid" placeholder="Número leído de la etiqueta del parabrisas"><small class="text-body-secondary">Premier: esta es la credencial que autentica el vehículo.</small></div><div class="col-md-6"><label class="form-label">Marca</label><input class="form-control" name="make" id="vehicleMake"></div><div class="col-md-6"><label class="form-label">Modelo</label><input class="form-control" name="model" id="vehicleModel"></div><div class="col-md-6"><label class="form-label">Color</label><input class="form-control" name="color" id="vehicleColor"></div><div class="col-12"><label class="form-label">Niveles de acceso ZK para el vehículo</label><select class="form-select" name="zk_access_level_ids[]" id="vehicleZkLevels" multiple size="4"><?php foreach($zkLevels as $zl):$zn=mb_strtoupper((string)($zl['name']??''));if(!str_starts_with($zn,'VEHICULOS '))continue;?><option value="<?=e($zl['external_id'])?>"><?=e($zl['name'])?></option><?php endforeach;?></select><small class="text-body-secondary">Selecciona solo los accesos vehiculares que correspondan. Property no otorgará automáticamente todos los niveles.</small></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="sync_zkbio" id="vehicleSyncZk" checked><span class="form-check-label">Provisionar en ZKBio como identidad vehicular con RFID/cardNo (modelo real de Premier)</span></label></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div></form></div></div>

<script>
document.addEventListener('DOMContentLoaded',()=>{const modal=document.getElementById('vehicleAdminModal');modal?.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let d={};if(b?.classList.contains('js-edit-vehicle')){try{d=JSON.parse(b.dataset.json||'{}')}catch(_){}}document.getElementById('vehicleModalTitle').textContent=d.id?'Editar vehículo':'Nuevo vehículo';document.getElementById('vehicleId').value=d.id||'';document.getElementById('vehicleDisplay').value=d.display_name||'';document.getElementById('vehicleProperty').value=d.property_id||'';document.getElementById('vehiclePerson').value=d.person_id||'';document.getElementById('vehiclePlate').value=d.plate||'';document.getElementById('vehicleRfid').value=d.rfid_card_no||'';document.getElementById('vehicleMake').value=d.make||'';document.getElementById('vehicleModel').value=d.model||'';document.getElementById('vehicleColor').value=d.color||'';document.getElementById('vehicleSyncZk').checked=!d.id;const selected=String(d.zk_access_level_ids||'').split(',').filter(Boolean);document.querySelectorAll('#vehicleZkLevels option').forEach(o=>o.selected=selected.includes(o.value));});});
</script>
